def rollout(candidate, current, metrics, thresholds):
    findings = validate_release(candidate)
    if findings:
        return Decision('REJECT', current.release_id, findings)
    failures = evaluate_canary(metrics, thresholds)
    if failures:
        return Decision('ROLLBACK', current.release_id, failures)
    return Decision('PROMOTE', candidate.release_id, ())
